{"cards": [{"node_code": "N_63288d04bb78919e", "definition": "水路运输运营过程中的技术组织、作业流程、设备使用、安全管理及业务规范，涵盖港口、船舶、装卸、航线及轮渡等具体技术管理环节。", "boundary": "本节点聚焦于“技术”与“操作”层面的管理，如调度、工艺、安全规程、设备维护及业务执行。边界在于区分“技术管理”与“经济管理”（成本、运价、投资归入水路运输经济）、“基础设施工程”（航道、港口建设归入航道/港口工程）、“船舶设计制造”（归入船舶工程）。若涉及水运政策、法规的宏观制定，需视具体内容侧重技术执行还是行政决策，侧重执行归本节点。", "includes": ["港口与船舶的调度、作业组织及安全技术规程", "货物装卸、传送工艺、设备使用及货场管理", "航线管理、轮渡运营、水运业务（客货）操作规范及世界航运业技术概况"], "excludes": ["水路运输的成本、运价、票价及投资经济分析", "航道、港口、船闸等基础设施的工程设计、施工与结构", "船舶的总体设计、建造工艺、修理及拆船技术"], "sibling_distinctions": [{"other_code": "N_f351ffdebeb4d928", "rule": "本节点侧重“怎么做”（技术操作、流程、安全、设备使用），兄弟节点侧重“算账与决策”（成本、运价、经济效益、宏观政策）。"}, {"other_code": "N_db907cc576cd250b", "rule": "本节点侧重港口建成后的“运营组织与管理”，兄弟节点侧重港口的“工程建设、结构与设施设计”。"}, {"other_code": "N_e288166af7250639", "rule": "本节点侧重航道建成后的“航线管理与通航组织”，兄弟节点侧重航道的“疏浚、整治、护岸等工程技术”。"}, {"other_code": "N_86a119d0c700afcb", "rule": "本节点侧重传统及通用的技术管理流程与规范，兄弟节点侧重基于数字化、智能化、无人化等新技术的系统与感知技术。"}], "cross_boundary_rule": "若内容涉及“智慧港口”或“智能航运”的具体技术实现（如算法、传感器、数字孪生），主挂载智慧水运系统；若仅涉及利用新技术优化传统调度流程的管理制度，可挂载本节点。"}, {"node_code": "N_f351ffdebeb4d928", "definition": "水路运输领域的经济规律、成本运价理论、宏观发展政策、管理体制及国内外水路运输经济状况的分析与研究。", "boundary": "本节点聚焦于“经济”属性，包括成本核算、运价制定、投资效益、产业政策、市场分析及历史经济演变。边界在于区分“经济”与“技术管理”（具体操作流程、安全规程归入技术管理）、“工程”（基础设施造价归入工程节点，本节点侧重全生命周期经济评价）。若涉及具体企业的财务审计细节，需视是否具备行业普遍性，一般归入企业经营管理或相关经济节点。", "includes": ["水路运输成本、运价、票价理论及经济分析", "水路运输建设发展理论、方针政策、管理体制及历史", "世界及中国水路运输经济概况、联合运输经济及地方水运经济"], "excludes": ["具体的船舶调度、港口作业流程、安全技术规程等操作性内容", "航道、港口、船舶的工程设计与施工技术细节", "纯法律条文解读（除非涉及经济法规或政策背景）"], "sibling_distinctions": [{"other_code": "N_63288d04bb78919e", "rule": "本节点侧重“价值与效益”（钱、政策、市场、理论），兄弟节点侧重“技术与操作”（流程、设备、安全、执行）。"}, {"other_code": "N_86a119d0c700afcb", "rule": "本节点侧重经济层面的分析，兄弟节点侧重技术层面的智能化系统构建。若涉及智慧水运的经济效益评估，主挂载本节点。"}], "cross_boundary_rule": "若内容涉及“智慧水运”的投资回报或经济影响，主挂载本节点；若涉及智慧水运的技术架构，主挂载智慧水运系统。"}, {"node_code": "N_86a119d0c700afcb", "definition": "应用数字化、智能化、物联网及空间信息技术构建的水运感知、运营控制及空间信息管理系统，涵盖数字孪生、无人系统及智能管控。", "boundary": "本节点聚焦于“新技术”在水运领域的应用，特别是数字化感知、智能算法、无人装备及GIS/海洋工程信息化。边界在于区分“智慧系统”与“传统技术管理”（常规调度、人工操作归入技术管理）、“基础通信”（通用通信协议归入通信类，本节点侧重水运专用应用）。若涉及具体的传感器硬件制造，需视是否属于水运专用，通用硬件归入电子/机械类。", "includes": ["水运信息数字化、河流海洋智能感知及数字孪生技术", "数智水运系统优化、船岸协同智能管控及水运无人系统", "海洋地理信息系统（GIS）及智能海洋工程信息化技术"], "excludes": ["传统的人工调度、纸质单据流转及非智能化的常规作业流程", "通用的计算机硬件、网络基础设施或通信协议（非水运专用）", "水路运输的经济成本分析或宏观政策制定"], "sibling_distinctions": [{"other_code": "N_63288d04bb78919e", "rule": "本节点侧重“智能化/数字化”技术实现（算法、感知、无人），兄弟节点侧重“常规/通用”技术管理流程与规范。"}, {"other_code": "N_f351ffdebeb4d928", "rule": "本节点侧重“技术系统”本身，兄弟节点侧重“经济价值”分析。"}], "cross_boundary_rule": "若内容涉及智慧水运系统的“技术架构、算法、感知设备”，主挂载本节点；若涉及其“经济效益、投资模式”，主挂载水路运输经济；若涉及“管理制度变革”，可关联技术管理。"}]}
